import matplotlib.pyplot as plt

# 1. Variables to store extracted data
energia_cloud = 0.0
energia_fog = 0.0
energia_edge_lista = []

latencia_raw = 0.0
latencia_critica = 0.0
latencia_response = 0.0

red_total = 0.0

# 2. Read the text file generated by iFogSim
try:
    with open('salida_consola.txt', 'r') as file:
        lineas = file.readlines()

    # 3. Parse line by line to find results
    for linea in lineas:
        # Extract Energy
        if "cloud : Energy Consumed" in linea:
            energia_cloud = float(linea.split('=')[1].strip())
        elif "FogServer_Hospital : Energy Consumed" in linea:
            energia_fog = float(linea.split('=')[1].strip())
        elif "Edge_Paciente_" in linea and "Energy Consumed" in linea:
            energia_edge_lista.append(float(linea.split('=')[1].strip()))
        
        # Extract Tuple Latency
        elif "RAW_DATA --->" in linea:
            latencia_raw = float(linea.split('--->')[1].strip())
        elif "Crítica --->" in linea:
            latencia_critica = float(linea.split('--->')[1].strip())
        elif "RESPONSE --->" in linea:
            latencia_response = float(linea.split('--->')[1].strip())
            
        # Extract Network Usage
        elif "Total network usage" in linea:
            red_total = float(linea.split('=')[1].strip())

except FileNotFoundError:
    print("Error: File 'salida_consola.txt' not found.")
    exit()

# Calculate average energy of Edge nodes (Gateways)
energia_edge_promedio = sum(energia_edge_lista) / len(energia_edge_lista) if energia_edge_lista else 0.0

# ==========================================
# GRAPH 1: Tuple Latency (Execution Delay)
# ==========================================
plt.figure(figsize=(8, 5))
tuplas = ['RAW_DATA\n(Normal)', 'Critical\n(Anomaly)', 'RESPONSE\n(Alarm)']
latencias = [latencia_raw, latencia_critica, latencia_response]

barras_latencia = plt.bar(tuplas, latencias, color=['#A9A9A9', '#B22222', '#4682B4'])
plt.title('Processing Latency by Tuple Type (E-Health)', fontsize=14, fontweight='bold')
plt.ylabel('Delay Time / Latency (ms)', fontsize=12)
plt.grid(axis='y', linestyle='--', alpha=0.7)

for barra in barras_latencia:
    yval = barra.get_height()
    plt.text(barra.get_x() + barra.get_width()/2, yval, f'{yval:.2f} ms', ha='center', va='bottom', fontweight='bold')

plt.tight_layout()
plt.savefig('graph_1_latency.png', dpi=300)

# ==========================================
# GRAPH 2: Energy Consumption
# ==========================================
plt.figure(figsize=(8, 5))
entidades = ['Cloud\n(Tier 4)', 'Fog Server\n(Tier 3)', 'Edge Average\n(Tier 2)']
energia = [energia_cloud, energia_fog, energia_edge_promedio] 

barras_energia = plt.bar(entidades, energia, color=['#778899', '#4682B4', '#D2691E'])
plt.title('Energy Consumption by Hierarchical Tier', fontsize=14, fontweight='bold')
plt.ylabel('Energy Consumed (W*s)', fontsize=12)
plt.grid(axis='y', linestyle='--', alpha=0.7)

for barra in barras_energia:
    yval = barra.get_height()
    plt.text(barra.get_x() + barra.get_width()/2, yval + (max(energia)*0.02), f'{int(yval)}', ha='center', va='bottom', fontweight='bold')

plt.tight_layout()
plt.savefig('graph_2_energy.png', dpi=300)

# ==========================================
# GRAPH 3: Total Network Usage (Bandwidth)
# ==========================================
plt.figure(figsize=(6, 5))
plt.bar(['Proposed Heuristic\n(CriticalityAware)'], [red_total], color='#2E8B57', width=0.5)
plt.title('Total Network Bandwidth Consumption', fontsize=14, fontweight='bold')
plt.ylabel('Network Usage (Bytes)', fontsize=12)
plt.grid(axis='y', linestyle='--', alpha=0.7)
plt.text(0, red_total + (red_total*0.02), f'{int(red_total)} Bytes', ha='center', va='bottom', fontweight='bold', fontsize=12)

plt.tight_layout()
plt.savefig('graph_3_network.png', dpi=300)

print("Single evaluation graphs generated successfully in English!")
